impl fmt::Display for BlockSymbol {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        use BlockSymbol::*;
        use colored::Colorize;
        let s0 = match *self {
            Run(RunSymbolType::X, _) => "",
            // Run(t, _) => &format!("{:?}", t),
            Left => "<",
            LeftInv => "<^-1",
            _ => &format!("{:?}", self),
        };
        let s1 = match *self {
            T => s0.blue().bold(),
            Q => s0.green().bold(),
            L | R => s0.dimmed(),
            Left | LeftInv => s0.red().bold().dimmed(),
            _ => s0.into(),
        };
        let s_exp = match *self {
            Run(RunSymbolType::X, n) => &format!("{n}"),
            // Run(_, n) => {
            //     if n == 1 {
            //         ""
            //     } else {
            //         &format!("^{}", n)
            //     }
            // }
            _ => "",
        };
        write!(f, "{}{}", s1, s_exp)
    }
}

