#[derive(Debug)]
enum StepType {
    Basic,
    LongA,
    LongAStop,
    LongLeftCancel,
    RegularResume,
    LeftNull,
}

impl StepType {
    fn is_stride(&self) -> bool {
        match self {
            Self::Basic => false,
            Self::LeftNull => true,
            Self::LongA => true,
            Self::LongAStop => false,
            Self::LongLeftCancel => true,
            Self::RegularResume => false,
        }
    }
}

fn get_next_between_X_exp(rest: &[BlockSymbol]) -> Option<(Exp, &[BlockSymbol])> {
    use BlockSymbol::*;
    use RunSymbolType::X;
    if let [rest2 @ .., Run(X, n), Q | T] = rest {
        Some((*n, rest2))
    } else if let [rest2 @ .., Q | T] = rest
        && matches!(rest2, [.., Q | T])
    {
        Some((0, rest2))
    } else {
        None
    }
}

impl BlockSimulator {
    fn new(long_a: bool) -> Self {
        use BlockSymbol::*;
        use RunSymbolType::*;
        // L C > X X R
        // L X T > X X R
        // L X T > X R1
        Self {
            left_tape: vec![L, Run(X, 1), T],
            right_tape: vec![R1, Run(X, 1)],
            state: HigherState::Right,
            base_steps: 18,
            self_steps: 0,
            notable_steps: 0,
            long_a,
        }
    }

    pub fn step(&mut self) -> Result<StepType, SimError> {
        let t = self.inner_step()?;
        self.self_steps += 1;

        if !t.is_stride() {
            self.notable_steps += 1;
        }
        Ok(t)
    }

    pub fn inner_step(&mut self) -> Result<StepType, SimError> {
        if self.long_a {
            if self.state == HigherState::LeftNull {
                match self.left_tape.last() {
                    Some(BlockSymbol::Left) => {
                        self.left_tape.pop();
                        self.state = HigherState::Left;
                        return Ok(StepType::RegularResume);
                    }
                    Some(_) => {
                        let t = self.left_tape.pop().unwrap();
                        self.right_tape.push(t);
                        return Ok(StepType::LeftNull);
                    }
                    _ => panic!("oh no"),
                }
            }
            if self.state == HigherState::Left
                && self.left_tape.last() == Some(&BlockSymbol::LeftInv)
            {
                self.left_tape.pop();
                self.state = HigherState::LeftNull;
                return Ok(StepType::LongLeftCancel);
            } else if let Some((new_base_steps, step_type)) = self.process_long_a() {
                self.base_steps += new_base_steps;
                return Ok(step_type);
            }
        }

        let new_base_steps = self.basic_step()?;
        self.base_steps = self.base_steps.checked_add(new_base_steps.into()).unwrap();
        Ok(StepType::Basic)
    }

    pub fn long_sim_active(&self) -> bool {
        if self.state == HigherState::LeftNull || self.state == HigherState::RightALong {
            return true;
        }
        self.left_tape
            .iter()
            .any(|&t| t == BlockSymbol::Left || t == BlockSymbol::LeftInv)
    }

    pub fn process_long_a(&mut self) -> Option<(Exp, StepType)> {
        use BlockSymbol::*;
        use RunSymbolType::X;

        let is_long_sim = match &self.state {
            HigherState::RightA => false,
            HigherState::RightALong => true,
            _ => return None,
        };

        if is_long_sim {
            match self.right_tape.as_mut_slice() {
                // a m R1 -> m+1 T 2 R1 (4m + 34)
                [R1, Run(X, m0 @ 1..)] => {
                    let m = *m0;
                    add_or_merge_run(&mut self.left_tape, X, m + 1);
                    self.right_tape.pop();
                    self.right_tape.extend_from_slice(&[Run(X, 2), T]);
                    self.state = HigherState::LeftNull;
                    return Some((4 * m + 34, StepType::LongLeftCancel));
                }
                // a m T n R1 -> m T n+4 R1 (4m + 8n + 46) (m >= 1)
                [R1, Run(X, n), T, Run(X, m0 @ 1..)] => {
                    let n0 = *n;
                    let m = *m0;
                    *n += 4;
                    add_or_merge_run(&mut self.left_tape, X, m);
                    self.right_tape.pop();
                    self.state = HigherState::LeftNull;
                    return Some((4 * m + 8 * n0 + 46, StepType::LongLeftCancel));
                }
                _ => (),
            }
        }

        enum Task {
            None,
            T { m: Exp, n: Exp, s2: BlockSymbol },
            Q { m: Exp, n: Exp },
        }

        fn match_task_T(m: Exp, n: Exp, s2: BlockSymbol, p: Exp, rest: &[BlockSymbol]) -> Task {
            // hack
            if n + p <= 3 {
                return Task::None;
            }
            // hack 2
            if let [.., T, T] = rest {
                return Task::None;
            }
            // hack 3
            if let Some((p2, rest2)) = get_next_between_X_exp(rest)
                && let Some((p3, _)) = get_next_between_X_exp(rest2)
                && p + p2 + p3 <= 4
            {
                return Task::None;
            }

            let next_m = p - 1;
            if let [.., Q] = rest
                && next_m < 3
            {
                Task::None
            } else if let [.., T] = rest
                && next_m < 1
            {
                Task::None
            } else {
                Task::T { m, n, s2 }
            }
        }

        fn match_task_Q(m: Exp, n: Exp, p: Exp, rest: &[BlockSymbol]) -> Task {
            let next_m = p + 2;
            if let [.., Q] = rest
                && next_m < 3
            {
                Task::None
            } else {
                Task::Q { m, n }
            }
        }

        let task: Task = if self.left_tape.len() <= 6 {
            Task::None
        } else {
            match self.right_tape.as_slice() {
                // a m T n Q p -> m T n+1 Q a p-1
                // a m T n T p -> m T n+1 T a p-1
                // (m >= 1, n >= 0, p >= 1)
                [
                    rest @ ..,
                    Run(X, p @ 1..),
                    s2 @ (Q | T),
                    Run(X, n @ 1..),
                    T,
                    Run(X, m @ 1..),
                ] => match_task_T(*m, *n, *s2, *p, rest),
                [rest @ .., Run(X, p @ 1..), s2 @ (Q | T), T, Run(X, m @ 1..)] => {
                    match_task_T(*m, 0, *s2, *p, rest)
                }
                // a m Q n T p -> m-2 T n Q a p+2 (4m + 34n + 12)
                // (m >= 3, n >= 1, p >= 0)
                [
                    rest @ ..,
                    Run(X, p @ 1..),
                    T,
                    Run(X, n @ 1..),
                    Q,
                    Run(X, m @ 3..),
                ] => match_task_Q(*m, *n, *p, rest),
                [rest @ .., T, Run(X, n @ 2..), Q, Run(X, m @ 3..)] => {
                    match_task_Q(*m, *n, 0, rest)
                }
                _ => Task::None,
            }
        };

        match task {
            Task::None => {
                if is_long_sim {
                    self.left_tape.push(LeftInv);
                    self.state = HigherState::RightA;
                    Some((0, StepType::LongAStop))
                } else {
                    None
                }
            }
            _ => {
                if !is_long_sim {
                    self.left_tape.push(Left);
                    self.state = HigherState::RightALong;
                }
                match task {
                    Task::T { m, n, s2 } => {
                        self.right_tape.pop();
                        self.right_tape.pop();
                        if n > 0 {
                            self.right_tape.pop();
                        }
                        self.right_tape.pop();
                        decrement_run(&mut self.right_tape, X);
                        add_or_merge_run(&mut self.left_tape, X, m);
                        self.left_tape.extend_from_slice(&[T, Run(X, n + 1), s2]);
                        let n_steps = match s2 {
                            Q => 4 * m + 8 * n + 28,
                            T => 4 * m + 8 * n + 24,
                            _ => unreachable!(),
                        };
                        Some((n_steps, StepType::LongA))
                    }
                    Task::Q { m, n } => {
                        for _ in 0..4 {
                            self.right_tape.pop();
                        }
                        add_or_merge_run(&mut self.right_tape, X, 2);
                        let madd = m - 2;
                        if madd > 0 {
                            add_or_merge_run(&mut self.left_tape, X, madd);
                        }
                        self.left_tape.extend_from_slice(&[T, Run(X, n), Q]);
                        Some((4 * m + 34 * n + 12, StepType::LongA))
                    }
                    _ => unreachable!(),
                }
            }
        }
    }
}

fn compare_long_sim() {
    let mut sim = BlockSimulator::new(false);
    let mut long_sim = BlockSimulator::new(true);
    let max_steps = 2000000;

    for _ in 1..=max_steps {
        long_sim.step().unwrap();
        if !long_sim.long_sim_active() {
            while sim.base_steps < long_sim.base_steps {
                // println!("S: {sim}");
                sim.step().unwrap();
            }
        }
        if sim.base_steps == long_sim.base_steps
        // || (long_sim.self_steps >= 1765 && long_sim.self_steps <= 1870)
        {
            println!("S: {sim}");
            println!("L: {long_sim}");
        }
    }
    println!("{sim}");
    println!("{long_sim}");
}

fn max_x_exp(v: &Vec<BlockSymbol>) -> Exp {
    let mut m: Exp = 0;
    for s in v {
        if let BlockSymbol::Run(RunSymbolType::X, n) = s {
            m = m.max(*n);
        }
    }
    m
}

use itertools::Itertools;
use nibble_vec::Nibblet;
use radix_trie::{Trie, TrieCommon, TrieKey};

#[derive(PartialEq, Eq)]
struct EncodedHalfTape(Nibblet);

impl EncodedHalfTape {
    fn from_tape(v: &Vec<BlockSymbol>) -> Self {
        use BlockSymbol::*;
        use RunSymbolType::X;
        // 1111: Q, 1110: T,
        // 1101 xxxx xxxx: X^n
        // 10xx xxxx: X^n
        // 0xxx: X^n

        assert!(v.first() == Some(&R1));
        let mut out = Nibblet::new();
        for s in &v[1..] {
            match s {
                Q => {
                    out.push(15);
                }
                T => {
                    out.push(14);
                }
                Run(X, n @ 0..8) => {
                    out.push(*n as u8);
                }
                Run(X, n @ 8..64) => {
                    let n2 = *n as u8;
                    let right = n2 % 16;
                    let left = n2 / 16 + 8;
                    out.push(left);
                    out.push(right);
                }
                Run(X, n @ 64..256) => {
                    let n2 = *n as u8;
                    let right = n2 % 16;
                    let left = n2 / 16;
                    out.push(13);
                    out.push(left);
                    out.push(right);
                }
                _ => {
                    eprintln!("{s}");
                    unimplemented!()
                }
            }
        }

        Self(out)
    }

    fn to_tape(&self) -> Vec<BlockSymbol> {
        use BlockSymbol::*;
        use RunSymbolType::X;

        let mut out = vec![R1];
        let mut i = 0;
        while i < self.0.len() {
            match self.0.get(i) {
                16.. => unreachable!(),
                15 => {
                    out.push(Q);
                    i += 1;
                }
                14 => {
                    out.push(T);
                    i += 1;
                }
                13 => {
                    let left = self.0.get(i + 1);
                    let right = self.0.get(i + 2);
                    let n = (left * 16 + right) as Exp;
                    out.push(Run(X, n));
                    i += 3;
                }
                12 => unreachable!(),
                left0 @ 8..12 => {
                    let left = left0 - 8;
                    let right = self.0.get(i + 1);
                    let n = (left * 16 + right) as Exp;
                    out.push(Run(X, n));
                    i += 2;
                }
                n @ 0..8 => {
                    out.push(Run(X, n as Exp));
                    i += 1;
                }
            }
        }

        out
    }
}

impl TrieKey for EncodedHalfTape {
    fn encode(&self) -> Nibblet {
        self.0.clone()
    }
}

